import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { createRegistry, LogFileError, LeaseTakenError } from './src/index.js';

function fakeClock(start = 0) {
  let now = start;
  const clock = () => now;
  clock.set = (v) => { now = v; };
  clock.advance = (d) => { now += d; };
  return clock;
}

let passed = 0;
function check(name, fn) {
  fn();
  passed += 1;
  console.log(`ok - ${name}`);
}

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lease-log-'));
const logPath = path.join(dir, 'lease.log');

// --- Life before restart: grant, renew, early release, expiry ---
const clock1 = fakeClock(0);
let r = createRegistry({ ttlMs: 100, clock: clock1, logPath });
const a = r.acquire('keep', 'h1', 100);
const b = r.acquire('renewed', 'h2', 40);
const c = r.acquire('freed', 'h3', 100);
const d = r.acquire('expired', 'h4', 10);
clock1.set(30);
assert.equal(r.renew(b.token), true); // expiresAt now 70
assert.equal(r.release(c.token), true);
clock1.set(50);
assert.deepEqual(r.sweep(), ['expired']);
assert.deepEqual(r.stats(), { granted: 4, renewed: 1, released: 1, reclaimed: 1, live: 2 });

// --- Restart: replay ---
const clock2 = fakeClock(50);
r = createRegistry({ ttlMs: 100, clock: clock2, logPath });

check('counters survive restart with no extra increments', () => {
  assert.deepEqual(r.stats(), { granted: 4, renewed: 1, released: 1, reclaimed: 1, live: 2 });
});

check('unexpired leases stay live and occupied', () => {
  assert.equal(r.holder('keep'), 'h1');
  assert.equal(r.holder('renewed'), 'h2');
  assert.equal(r.holder('freed'), null);
  assert.equal(r.holder('expired'), null);
});

check('pre-restart credentials are void for renew and release', () => {
  assert.equal(r.renew(a.token), false);
  assert.equal(r.release(a.token), false);
  assert.equal(r.renew(b.token), false);
  assert.equal(r.release(b.token), false);
  // counters untouched
  assert.deepEqual(r.stats(), { granted: 4, renewed: 1, released: 1, reclaimed: 1, live: 2 });
});

check('a live replayed lease still blocks acquire', () => {
  assert.throws(() => r.acquire('keep', 'other', 10), (e) => e instanceof LeaseTakenError && e.code === 'LEASE_TAKEN');
  assert.equal(r.stats().granted, 4);
});

check('replayed lease expiry instant drops live count; sweep reclaims in expiry order', () => {
  // 'renewed' expires 70, 'keep' expires 100
  clock2.set(70);
  assert.equal(r.stats().live, 1);
  assert.deepEqual(r.sweep(), ['renewed']);
  assert.equal(r.stats().reclaimed, 2);
  clock2.set(100);
  assert.deepEqual(r.sweep(), ['keep']);
  assert.deepEqual(r.stats(), { granted: 4, renewed: 1, released: 1, reclaimed: 3, live: 0 });
});

// --- Restart again: nothing live, counters intact ---
const clock3 = fakeClock(100);
r = createRegistry({ ttlMs: 100, clock: clock3, logPath });
check('second restart keeps cumulative counters and zero live', () => {
  assert.deepEqual(r.stats(), { granted: 4, renewed: 1, released: 1, reclaimed: 3, live: 0 });
});

check('new tokens never collide with replayed (even released/reclaimed) tokens', () => {
  const t1 = r.acquire('x', 'h', 10).token;
  const t2 = r.acquire('y', 'h', 10).token;
  assert.notEqual(t1, a.token);
  assert.notEqual(t1, b.token);
  assert.notEqual(t1, c.token);
  assert.notEqual(t1, d.token);
  assert.notEqual(t2, t1);
});

// --- Missing log file: fresh start, no throw ---
const emptyPath = path.join(dir, 'does-not-exist.log');
check('missing log behaves like a fresh registry', () => {
  const rr = createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: emptyPath });
  assert.deepEqual(rr.stats(), { granted: 0, renewed: 0, released: 0, reclaimed: 0, live: 0 });
  rr.acquire('z', 'h');
  assert.ok(fs.existsSync(emptyPath));
});

// --- Corrupt line / unknown version ---
const corruptPath = path.join(dir, 'corrupt.log');
fs.writeFileSync(corruptPath, '{"v":1,"type":"acquire","token":"t","resource":"r","holder":"h","ttlMs":10,"expiresAt":10}\n{not json\n');
check('corrupt line throws LogFileError with code', () => {
  assert.throws(() => createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: corruptPath }),
    (e) => e instanceof LogFileError && e.code === 'LOG_FILE_ERROR');
});
const badVersionPath = path.join(dir, 'badver.log');
fs.writeFileSync(badVersionPath, '{"v":99,"type":"acquire"}\n');
check('unknown version throws LogFileError with code', () => {
  assert.throws(() => createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: badVersionPath }),
    (e) => e instanceof LogFileError && e.code === 'LOG_FILE_ERROR');
});
const unknownTypePath = path.join(dir, 'badevent.log');
fs.writeFileSync(unknownTypePath, '{"v":1,"type":"nope"}\n');
check('unknown event type throws LogFileError with code', () => {
  assert.throws(() => createRegistry({ ttlMs: 10, clock: fakeClock(0), logPath: unknownTypePath }),
    (e) => e instanceof LogFileError && e.code === 'LOG_FILE_ERROR');
});

// --- Write failure rolls back the operation ---
const roDir = path.join(dir, 'readonly');
fs.mkdirSync(roDir);
const roPath = path.join(roDir, 'lease.log');
// pre-create one live lease via a good log, then make the directory unwritable
fs.writeFileSync(roPath, JSON.stringify({ v: 1, type: 'acquire', at: 0, token: 'old-t', resource: 'r', holder: 'h', ttlMs: 100, expiresAt: 100 }) + '\n');
fs.chmodSync(roDir, 0o500);
try {
  const rr = createRegistry({ ttlMs: 100, clock: fakeClock(0), logPath: roPath });
