  rbClock.set(20);
  sabotage(rollbackPath);
  try {
    assert.throws(() => rb.renew(rbLease.token), LogFileError);
  } finally {
    restore(rollbackPath);
  }
  assert.equal(rb.stats().renewed, 0);
  // original expiry 100 still governs: at 100 it is gone
  rbClock.set(100);
  assert.equal(rb.holder('r1'), null);
  rbClock.set(20);
});

