  const l = rr.acquire('r', 'h');
  assert.equal(rr.renew('nope'), false);
  assert.equal(rr.release('nope'), false);
  cl.set(10);
  assert.equal(rr.renew(l.token), false);
  assert.equal(rr.release(l.token), false);
  assert.deepEqual(rr.stats(), { granted: 1, renewed: 0, released: 0, reclaimed: 0, live: 0 });
