  // The clock reading is part of the credential. Pids and instance ids can
  // coincide after a restart, so skip any sequence that collides with a
  // token reconstructed from the log.
  let token;
  do {
    tokenSequence += 1;
    token = `lease-${process.pid}-${registryId}-${tokenSequence}-${now.toString(36)}`;
  } while (knownTokens.has(token));
  knownTokens.add(token);
  return token;
}

