  v: LOG_VERSION,
  type: 'acquire',
  at: now,
  token,
  resource,
  holder,
  ttlMs,
  expiresAt,
});

if (currentToken !== undefined) {
  occupied.delete(resource);
  leases.delete(currentToken);
}

